import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import org.junit.Assert.*
import org.junit.Test
import java.util.UUID

// 1. Data class Task
data class Task(
    val id: Long = UUID.randomUUID().mostSignificantBits,
    val title: String,
    val isCompleted: Boolean = false
)

// 2. TodoViewModel
class TodoViewModel : ViewModel() {
    private val _tasks = MutableStateFlow<List<Task>>(emptyList())
    val tasks: StateFlow<List<Task>> = _tasks.asStateFlow()

    fun addTask(title: String) {
        val newTask = Task(
            id = System.currentTimeMillis(),
            title = title
        )
        _tasks.value = _tasks.value + newTask
    }

    fun deleteTask(id: Long) {
        _tasks.value = _tasks.value.filter { it.id != id }
    }

    fun toggleTask(id: Long) {
        _tasks.value = _tasks.value.map { task ->
            if (task.id == id) task.copy(isCompleted = !task.isCompleted)
            else task
        }
    }
}

// 3. Test class
class TodoViewModelTest {
    private val viewModel = TodoViewModel()

    @Test
    fun testAddTask() = runTest {
        val initialTasks = viewModel.tasks.value
        viewModel.addTask("Nouvelle tâche")

        assertEquals(initialTasks.size + 1, viewModel.tasks.value.size)
        assertEquals("Nouvelle tâche", viewModel.tasks.value.last().title)
    }

    @Test
    fun testDeleteTask() = runTest {
        viewModel.addTask("Tâche à supprimer")
        val taskToDelete = viewModel.tasks.value.first()

        val initialTasks = viewModel.tasks.value
        viewModel.deleteTask(taskToDelete.id)

        assertEquals(initialTasks.size - 1, viewModel.tasks.value.size)
        assertTrue(viewModel.tasks.value.none { it.id == taskToDelete.id })
    }

    @Test
    fun testToggleTask() = runTest {
        viewModel.addTask("Tâche à basculer")
        val task = viewModel.tasks.value.first()
        assertFalse(task.isCompleted)

        viewModel.toggleTask(task.id)
        assertTrue(viewModel.tasks.value.first().isCompleted)
    }
}

